import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";import"./chunks/assets.Dil_Czf7.js";var i=JSON.parse(`{"title":"Area E Dorms","description":"An overview of the Area E dormitories at SCUT University Town Campus","frontmatter":{"lang":"en-US","title":"Area E Dorms","description":"An overview of the Area E dormitories at SCUT University Town Campus","llm_translated":true},"headers":[],"relativePath":"en/infra/hemc/dorm-e.md","filePath":"en/infra/hemc/dorm-e.md","lastUpdated":1791510705000}`),a={name:`en/infra/hemc/dorm-e.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/hemc/dorm-e.md for this page in Markdown format</div><h1 id="area-e-dorms-overview" tabindex="-1">Area E Dorms Overview <a class="header-anchor" href="#area-e-dorms-overview" aria-label="Permalink to “Area E Dorms Overview”">​</a></h1><h2 id="_1-hardware" tabindex="-1">1. Hardware <a class="header-anchor" href="#_1-hardware" aria-label="Permalink to “1. Hardware”">​</a></h2><h3 id="a-inside-the-dorm" tabindex="-1">a. Inside the Dorm <a class="header-anchor" href="#a-inside-the-dorm" aria-label="Permalink to “a. Inside the Dorm”">​</a></h3><p>The room itself is not large, but since the buildings are newly built, the facilities are all fairly new.</p><p><img src="/assets/hemc/dorm_e_overview.jpg" alt="Full view of the dorm"></p><p><strong>Basic specs:</strong></p><ul><li>Dorms are generally four-person rooms measuring <strong>5m × 3.6m</strong></li><li>Lofted beds with desks underneath, plus your own wardrobe, bookshelf, and luggage rack</li></ul><p><strong>Desk:</strong></p><p><img src="/assets/hemc/dorm_e_desk.jpg" alt="Desk and storage cabinets"></p><ul><li>Size: <strong>1.2m × 0.6m</strong></li><li>One side connects to the stairs of the lofted bed, the other to the wardrobe</li><li>There is a bookshelf at the back on top, so plan the space wisely</li><li>The height gap between the bottom of the bookshelf and the desk is <strong>0.6m</strong></li></ul><p><strong>Wardrobe:</strong></p><ul><li>Roughly <strong>0.8m × 0.6m × 1.15m</strong></li><li>Below it sits a storage cabinet with the same width and length: <strong>0.8m × 0.6m × 0.45m</strong></li><li>Next to the wardrobe are four open cubbies (three on top measuring <strong>0.3m × 0.25m × 0.33m</strong> plus one at the very bottom measuring <strong>0.3m × 0.25m × 0.65m</strong>)</li></ul><p><strong>Right-side storage:</strong></p><ul><li>Drawers and cabinets for daily necessities and personal items</li><li>Drawers: <strong>0.4m × 0.33m × 0.1m</strong></li><li>Cabinet: <strong>0.6m × 0.33m × 0.45m</strong></li></ul><p><strong>Book cabinets:</strong></p><ul><li>Three book cabinets overhead, each <strong>0.4m × 0.2m</strong> (open at the top)</li></ul><p><strong>Staircase storage:</strong></p><ul><li>The stairs up to the bed are on the left/right side, with two storage compartments built into them <ul><li><strong>0.5m × 0.65m × 0.25m</strong></li><li><strong>0.5m × 0.4m × 0.25m</strong></li></ul></li><li>Since two people share one staircase, agree with your roommate on how to use them</li></ul><p><strong>Bed:</strong></p><ul><li>Size: <strong>1.9m × 0.9m</strong></li><li>The school automatically installs guardrails and a frame for hanging a mosquito net</li></ul><h3 id="b-balcony-toilet-and-shower" tabindex="-1">b. Balcony, Toilet, and Shower <a class="header-anchor" href="#b-balcony-toilet-and-shower" aria-label="Permalink to “b. Balcony, Toilet, and Shower”">​</a></h3><ul><li>The balcony is usually <strong>1.8m × 2.15m</strong> (in some dorms a corner is taken up by a wall)</li><li>There is a washbasin counter and a wash rack</li><li>The toilet and shower have a <strong>wet/dry separation</strong>, each roughly half the size of the balcony</li><li>Water: <strong>3.75 RMB/ton</strong></li><li>Electricity: <strong>0.6295 RMB/kWh</strong></li></ul><p><img src="/assets/hemc/dorm_e_balcony.jpg" alt="Balcony washbasin"></p><p><img src="/assets/hemc/dorm_e_bathroom.jpg" alt="Bathroom shower"></p><p><img src="/assets/hemc/dorm_e_toilet.jpg" alt="Toilet"></p><hr><h2 id="_2-software" tabindex="-1">2. Software <a class="header-anchor" href="#_2-software" aria-label="Permalink to “2. Software”">​</a></h2><ul><li>Each dorm comes with <strong>air conditioning</strong> and a <strong>fan</strong></li><li><strong>Water dispensers</strong> are at fixed spots on every floor</li><li><strong>Lights and power stay on all night</strong> (the campus network does cut out)</li><li>Each building should have <strong>7 elevators</strong></li><li><strong>e2/e3</strong> have an underground garage with stairs leading straight down (plus one elevator that goes to the garage)</li><li>Downstairs there are <strong>vending machines</strong> and <strong>food-delivery pickup points</strong> (delivery from the campus canteens or Xiya Supermarket can be sent here)</li><li>Each building has its own <strong>functional rooms and activity rooms</strong>, for example: <ul><li><strong>e2</strong>: kitchen, calligraphy room</li><li><strong>e3</strong>: psychological counseling room</li></ul></li></ul><hr><h2 id="_3-getting-around" tabindex="-1">3. Getting Around <a class="header-anchor" href="#_3-getting-around" aria-label="Permalink to “3. Getting Around”">​</a></h2><p>Area E really is quite far from most places on campus. Below are the routes and times to some important places (using <strong>e3</strong> as the example; e2 is about 50m closer, and e1 about 100m closer):</p><table tabindex="0"><thead><tr><th>Destination</th><th>Distance/Time</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Teaching buildings a5~a1</strong></td><td>500m ~ 700m</td><td>Listed from farthest to nearest; a1 is a tall building — cycle if you can and leave at least 15 minutes early</td></tr><tr><td><strong>Library</strong></td><td>about 800m</td><td>Right next to a1</td></tr><tr><td><strong>Teaching area sports field/gym</strong></td><td>about 800~900+m</td><td>About 20 minutes one way</td></tr><tr><td><strong>Lab buildings (starting with b)</strong></td><td>15~25 minutes</td><td>Varies from building to building</td></tr><tr><td><strong>Package pickup point</strong></td><td>Below e3 / next to Canteen 2</td><td>Occasionally it is the one below c10</td></tr><tr><td><strong>Food delivery (North Gate)</strong></td><td>about 8 minutes</td><td>Pickup is fairly convenient</td></tr><tr><td><strong>Suishi Village</strong></td><td>about 15 minutes</td><td>Food and shopping nearby</td></tr><tr><td><strong>Canteen 3</strong></td><td>about 15 minutes</td><td></td></tr><tr><td><strong>Next to Canteen 2 (Luckin Coffee / 遇见小面 (Yujian Xiaomian) / McDonald&#39;s)</strong></td><td>about 10 minutes</td><td></td></tr><tr><td><strong>GOGO Xintiandi (gogo新天地)</strong></td><td>about 25 minutes</td><td></td></tr><tr><td><strong>Nanting (南亭)</strong></td><td>about 30 minutes</td><td></td></tr><tr><td><strong>Beiting Village (北亭村)</strong></td><td>about 40 minutes</td><td></td></tr><tr><td><strong>Bio Island</strong></td><td>50 minutes or more</td><td>Better not to cycle</td></tr><tr><td><strong>Metro station (University Town Station)</strong></td><td>about 20 minutes</td><td>From the North Gate to Exit D; through campus and out the West Gate to Exit F</td></tr></tbody></table><blockquote><p><strong>Tip</strong>: Riding back to Area E from Exit F is a satisfying downhill all the way!</p></blockquote><hr><h2 id="_4-advice" tabindex="-1">4. Advice <a class="header-anchor" href="#_4-advice" aria-label="Permalink to “4. Advice”">​</a></h2><p>However nice the dorm is, what matters most is the <strong>people</strong>. Learn how to get along with your roommates, be as accommodating to one another as you can, and sort out responsibilities in advance.</p><p>Hope you have a wonderful time living in Area E at University Town!</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};